  -- ==== 清掉误标的 event（永久内容，不是节日）====
  -- 乌龟层按服务端 game_event 加的；pfQuest 见 event 就默认隐藏，图钉不画。
  -- 160 = T0.5 副本套装链，172 = 熔火之心传送门。AQ 开门链 (164) 暂不动，待实测。
  for _, qid in pairs({
    7487, 7848, 8905, 8906, 8907, 8908, 8909, 8910, 8911, 8912,
    8913, 8914, 8915, 8916, 8917, 8918, 8919, 8920, 8922, 8923,
